package com.raidslast;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import javax.inject.Inject;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

/**
 * Tracks the distinct unique items actually received from each raid, keyed off the
 * {@link LootReceived} event the built-in Loot Tracker plugin posts to the shared event bus. Only
 * items on a raid's {@link RaidType#getTrackedItemNames()} list count - common supplies and
 * currency are ignored. Persisted per RuneScape profile so they survive logouts and restarts.
 */
class RaidLootTracker
{
	static final String CONFIG_GROUP = "raidslast";
	static final int COLLECTION_OVERVIEW_GROUP_ID = InterfaceID.CollectionOverview.LATEST_ITEMS_DATA >>> 16;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	void onLootReceived(LootReceived lootReceived)
	{
		if (lootReceived.getType() != LootRecordType.EVENT)
		{
			return;
		}

		RaidType raidType = findRaidType(lootReceived.getName());
		if (raidType == null)
		{
			return;
		}

		ItemStack bestMatch = null;
		long bestValue = -1;
		for (ItemStack stack : lootReceived.getItems())
		{
			if (!isTrackedItem(raidType, stack.getId()))
			{
				continue;
			}

			int canonicalId = itemManager.canonicalize(stack.getId());
			long value = (long) itemManager.getItemPrice(canonicalId) * stack.getQuantity();
			if (value > bestValue)
			{
				bestValue = value;
				bestMatch = stack;
			}
		}

		if (bestMatch == null)
		{
			return;
		}

		// A witnessed drop is always the most recent thing we know about, so it belongs at the end.
		addItem(raidType, bestMatch.getId(), true);
	}

	/**
	 * Backfill from the real Collection Log page for a raid (its full obtained-item grid, not just
	 * a handful of recent unlocks), fired whenever that page is drawn - initial open or switching
	 * raid pages. Any tracked item the grid shows as obtained but that isn't already recorded gets
	 * added. Since the Collection Log carries no per-item timestamp, these are inserted at the
	 * front of the history rather than the end, so they can never masquerade as more recent than an
	 * item actually witnessed via {@link #onLootReceived}.
	 */
	void seedFromCollectionLogPage(String pageTitle, Widget itemsContainer)
	{
		RaidType raidType = findRaidType(pageTitle);
		if (raidType == null || itemsContainer == null)
		{
			return;
		}

		for (Widget itemWidget : itemsContainer.getDynamicChildren())
		{
			boolean obtained = itemWidget.getOpacity() == 0;
			int itemId = itemWidget.getItemId();
			if (!obtained || itemId <= 0 || !isTrackedItem(raidType, itemId))
			{
				continue;
			}

			addItem(raidType, itemId, false);
		}
	}

	/**
	 * Merges in the Collection Log overview's "Latest items" strip - the account's most recent
	 * unlocks, account-wide, assumed newest-first. Every item in it that matches a raid's tracked
	 * unique list is treated as a genuine recency signal, the same as a live drop, so multiple
	 * matches for the same raid end up correctly ordered relative to each other and relative to any
	 * item already recorded. This only catches first-time unlocks (the Collection Log doesn't track
	 * repeat drops) and only whatever still fits in that short strip - {@link #seedFromCollectionLogPage}
	 * is the completeness backstop for anything that's since rolled off it.
	 */
	void seedFromCollectionLogOverview(Widget latestItemsData)
	{
		if (latestItemsData == null)
		{
			return;
		}

		Widget[] items = latestItemsData.getDynamicChildren();
		// Walk oldest-to-newest so each later match correctly lands as more recent than the one
		// before it for its raid.
		for (int i = items.length - 1; i >= 0; i--)
		{
			int itemId = items[i].getItemId();
			if (itemId <= 0)
			{
				continue;
			}

			for (RaidType raidType : RaidType.values())
			{
				if (isTrackedItem(raidType, itemId))
				{
					addItem(raidType, itemId, true);
				}
			}
		}
	}

	/**
	 * Every item actually received from this raid so far, oldest first. The last element is the
	 * most recently received item.
	 */
	List<Integer> getReceivedItemIds(RaidType raidType)
	{
		String csv = configManager.getRSProfileConfiguration(CONFIG_GROUP, raidType.getConfigKey());
		if (csv == null || csv.isEmpty())
		{
			return new ArrayList<>();
		}

		List<Integer> ids = new ArrayList<>();
		for (String part : csv.split(","))
		{
			ids.add(Integer.valueOf(part));
		}
		return ids;
	}

	Optional<String> getLastItemName(RaidType raidType)
	{
		List<Integer> ids = getReceivedItemIds(raidType);
		if (ids.isEmpty())
		{
			return Optional.empty();
		}

		return Optional.of(itemManager.getItemComposition(ids.get(ids.size() - 1)).getName());
	}

	private void addItem(RaidType raidType, int itemId, boolean asMostRecent)
	{
		List<Integer> ids = getReceivedItemIds(raidType);
		if (ids.remove(Integer.valueOf(itemId)) && !asMostRecent)
		{
			// Already known and this isn't a fresh witnessed drop - leave its position alone.
			return;
		}

		if (asMostRecent)
		{
			ids.add(itemId);
		}
		else
		{
			ids.add(0, itemId);
		}

		StringBuilder csv = new StringBuilder();
		for (int i = 0; i < ids.size(); i++)
		{
			if (i > 0)
			{
				csv.append(',');
			}
			csv.append(ids.get(i));
		}

		configManager.setRSProfileConfiguration(CONFIG_GROUP, raidType.getConfigKey(), csv.toString());
	}

	private boolean isTrackedItem(RaidType raidType, int itemId)
	{
		String name = normalize(itemManager.getItemComposition(itemId).getName());
		return raidType.getTrackedItemNames().stream().anyMatch(tracked -> normalize(tracked).equals(name));
	}

	private static RaidType findRaidType(String name)
	{
		for (RaidType candidate : RaidType.values())
		{
			if (candidate.getLootEventName().equals(name))
			{
				return candidate;
			}
		}
		return null;
	}

	private static String normalize(String itemName)
	{
		int parenIdx = itemName.indexOf(" (");
		return (parenIdx == -1 ? itemName : itemName.substring(0, parenIdx)).toLowerCase();
	}
}

package com.raidslast;

import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.Set;
import lombok.Getter;

@Getter
enum RaidType
{
	COX(
		"Chambers of Xeric", "lastItemCox",
		orderedSetOf(
			"Twisted bow", "Elder maul", "Kodai insignia", "Dragon claws",
			"Ancestral hat", "Ancestral robe top", "Ancestral robe bottom",
			"Dinh's bulwark", "Dragon harpoon", "Twisted buckler",
			"Dexterous prayer scroll", "Arcane prayer scroll",
			"Metamorphic dust", "Twisted ancestral colour kit", "Olmlet"
		)
	),
	TOB(
		"Theatre of Blood", "lastItemTob",
		orderedSetOf(
			"Avernic defender hilt", "Justiciar faceguard", "Justiciar chestguard",
			"Justiciar legguards", "Ghrazi rapier", "Sanguinesti staff",
			"Scythe of vitur", "Lil' Zik"
		)
	),
	TOA(
		"Tombs of Amascut", "lastItemToa",
		orderedSetOf(
			"Masori mask", "Masori body", "Masori chaps", "Lightbearer",
			"Osmumten's fang", "Elidinis' ward", "Tumeken's shadow",
			"Thread of Elidinis", "Breach of the scarab", "Eye of the corruptor",
			"Jewel of the sun", "Jewel of Amascut", "Tumeken's guardian"
		)
	);

	private final String lootEventName;
	private final String configKey;

	/**
	 * Every item this raid's Collection Log tracks as a unique, in proper display case and a
	 * sensible reading order. Used both to render the sidebar panel's full list and, best-effort,
	 * to seed an empty "last item" from the Collection Log overview's "Latest items" panel. Loot
	 * actually witnessed via {@link net.runelite.client.plugins.loottracker.LootReceived} always
	 * takes priority and is never overwritten by that seeding.
	 */
	private final Set<String> trackedItemNames;

	RaidType(String lootEventName, String configKey, Set<String> trackedItemNames)
	{
		this.lootEventName = lootEventName;
		this.configKey = configKey;
		this.trackedItemNames = trackedItemNames;
	}

	private static Set<String> orderedSetOf(String... names)
	{
		return new LinkedHashSet<>(Arrays.asList(names));
	}
}

package com.raidslast;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(RaidsLastConfig.GROUP)
public interface RaidsLastConfig extends Config
{
	String GROUP = "raidslast";

	@ConfigItem(
		keyName = "crossPlayerLookups",
		name = "Resolve other players' commands",
		description = "Lets !coxlast, !toblast, !toalast, !raidslast and !raidslasttob resolve for "
			+ "other players too - and lets your own commands resolve for them - via a small relay "
			+ "server. With this off, only your own commands resolve, using only your own local data.",
		warning = "This plugin submits your IP address, and may submit various account data, to a "
			+ "3rd-party server not controlled or verified by RuneLite developers."
	)
	default boolean crossPlayerLookups()
	{
		return false;
	}
}

package com.raidslast;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.Font;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.CompoundBorder;
import javax.swing.border.LineBorder;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Lists, per raid, only the items this account has actually been recorded receiving - via a
 * witnessed {@link net.runelite.client.plugins.loottracker.LootReceived} or the Collection Log
 * overview seed - never the full theoretical unique table. The most recently received item in
 * each raid is highlighted.
 */
@Slf4j
class RaidsLastPanel extends PluginPanel
{
	private static final String NO_DROPS_YET = "No drops tracked yet";

	private final RaidLootTracker raidLootTracker;
	private final ItemManager itemManager;
	private final ClientThread clientThread;
	private final JPanel rowsPanel = new JPanel();

	RaidsLastPanel(RaidLootTracker raidLootTracker, ItemManager itemManager, ClientThread clientThread)
	{
		this.raidLootTracker = raidLootTracker;
		this.itemManager = itemManager;
		this.clientThread = clientThread;

		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		rowsPanel.setLayout(new BoxLayout(rowsPanel, BoxLayout.Y_AXIS));
		add(rowsPanel, BorderLayout.NORTH);

		rebuild();
	}

	@Override
	public void onActivate()
	{
		// Fired by a Swing mouse listener on the AWT event thread, not the client thread that
		// ItemManager's lookups here require - without this, clicking the tab throws
		// "must be called on client thread" and silently drops whichever raid section it hit.
		clientThread.invoke(this::rebuild);
	}

	void rebuild()
	{
		rowsPanel.removeAll();

		RaidType[] raidTypes = RaidType.values();
		for (int i = 0; i < raidTypes.length; i++)
		{
			RaidType raidType = raidTypes[i];
			rowsPanel.add(buildRaidHeader(raidType));
			rowsPanel.add(Box.createVerticalStrut(4));

			List<Integer> receivedItemIds = raidLootTracker.getReceivedItemIds(raidType);
			if (receivedItemIds.isEmpty())
			{
				rowsPanel.add(buildEmptyRow());
			}
			else
			{
				// Most recently received first; the very first row is this raid's "last item".
				for (int j = receivedItemIds.size() - 1; j >= 0; j--)
				{
					int itemId = receivedItemIds.get(j);
					try
					{
						rowsPanel.add(buildItemRow(itemId, j == receivedItemIds.size() - 1));
						rowsPanel.add(Box.createVerticalStrut(4));
					}
					catch (RuntimeException e)
					{
						// One bad row (e.g. item data not loaded yet) shouldn't blank out the rest
						// of this raid's section, or the raids after it.
						log.warn("Failed to build sidebar row for item {} in {}", itemId, raidType, e);
					}
				}
			}

			if (raidType == RaidType.TOB)
			{
				rowsPanel.add(Box.createVerticalStrut(4));
				rowsPanel.add(buildTobCommandNote());
			}

			if (i < raidTypes.length - 1)
			{
				rowsPanel.add(Box.createVerticalStrut(10));
			}
		}

		rowsPanel.revalidate();
		rowsPanel.repaint();
	}

	/**
	 * Another installed plugin (tob-qol) also registers {@code !toblast}. RuneLite only lets one
	 * plugin's handler answer a given command string - whichever starts up later silently wins, with
	 * no error - so {@code !toblast} can go quiet here through no fault of its own. Surfacing the
	 * guaranteed-unique {@code !raidslasttob} fallback in the panel means that's discoverable without
	 * having to already know why.
	 */
	private JLabel buildTobCommandNote()
	{
		JLabel note = new JLabel("<html><body style='width:190px'>"
			+ "Another plugin also uses <b>!toblast</b>, so it may not always respond. "
			+ "<b>!raidslasttob</b> always will.</body></html>");
		note.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		note.setFont(FontManager.getRunescapeSmallFont());
		note.setAlignmentX(LEFT_ALIGNMENT);
		return note;
	}

	private JLabel buildRaidHeader(RaidType raidType)
	{
		JLabel header = new JLabel(raidType.getLootEventName());
		header.setForeground(ColorScheme.BRAND_ORANGE);
		header.setFont(FontManager.getRunescapeBoldFont());
		header.setAlignmentX(LEFT_ALIGNMENT);
		return header;
	}

	private JLabel buildEmptyRow()
	{
		JLabel label = new JLabel(NO_DROPS_YET);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setAlignmentX(LEFT_ALIGNMENT);
		return label;
	}

	private JPanel buildItemRow(int itemId, boolean isLast)
	{
		JPanel row = new JPanel(new BorderLayout(8, 0));
		row.setAlignmentX(LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));
		row.setBackground(isLast ? ColorScheme.DARKER_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(isLast
			? new CompoundBorder(new LineBorder(ColorScheme.BRAND_ORANGE, 1), BorderFactory.createEmptyBorder(5, 7, 5, 7))
			: BorderFactory.createEmptyBorder(6, 8, 6, 8));

		JLabel iconLabel = new JLabel();
		iconLabel.setPreferredSize(new Dimension(28, 28));
		iconLabel.setHorizontalAlignment(SwingConstants.CENTER);
		AsyncBufferedImage image = itemManager.getImage(itemId);
		image.addTo(iconLabel);

		JLabel nameLabel = new JLabel(itemManager.getItemComposition(itemId).getName());
		nameLabel.setForeground(isLast ? ColorScheme.BRAND_ORANGE : ColorScheme.LIGHT_GRAY_COLOR);
		if (isLast)
		{
			nameLabel.setFont(nameLabel.getFont().deriveFont(Font.BOLD));
		}

		row.add(iconLabel, BorderLayout.WEST);
		row.add(nameLabel, BorderLayout.CENTER);
		return row;
	}
}

package com.raidslast;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatCommandManager;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ChatInput;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Raids Last",
	description = "Adds !coxlast, !toblast, !toalast and !raidslast chat commands showing off the last item you received from each raid, plus !raidslasttob as a fallback for !toblast.",
	tags = {"raids", "loot", "chat", "commands", "cox", "tob", "toa"}
)
public class RaidsLastPlugin extends Plugin
{
	private static final String COX_COMMAND = "!coxlast";
	private static final String TOB_COMMAND = "!toblast";
	private static final String TOA_COMMAND = "!toalast";
	private static final String COMBINED_COMMAND = "!raidslast";
	/**
	 * {@code !toblast} is also registered by the unrelated tob-qol plugin. RuneLite's
	 * ChatCommandManager keeps one shared map of command string to handler across every plugin, so
	 * whichever plugin starts up later silently overwrites the other's registration - there's no
	 * way for both to answer, and no error when it happens. This alias can't collide (nobody else
	 * has registered it), so it's the fallback for anyone whose {@code !toblast} gets shadowed.
	 */
	private static final String TOB_FALLBACK_COMMAND = "!raidslasttob";
	private static final String NO_ITEM_YET = "none yet";

	@Inject
	private Client client;

	@Inject
	private ChatCommandManager chatCommandManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private RaidLootTracker raidLootTracker;

	@Inject
	private RaidsLastRelay raidsLastRelay;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private RaidsLastConfig config;

	private RaidsLastPanel panel;
	private NavigationButton navigationButton;

	@Provides
	RaidsLastConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RaidsLastConfig.class);
	}

	@Override
	protected void startUp()
	{
		chatCommandManager.registerCommand(COX_COMMAND, (chatMessage, message) -> singleRaidLookup(chatMessage, RaidType.COX), this::publishToRelay);
		chatCommandManager.registerCommand(TOB_COMMAND, (chatMessage, message) -> singleRaidLookup(chatMessage, RaidType.TOB), this::publishToRelay);
		chatCommandManager.registerCommand(TOA_COMMAND, (chatMessage, message) -> singleRaidLookup(chatMessage, RaidType.TOA), this::publishToRelay);
		chatCommandManager.registerCommand(COMBINED_COMMAND, (chatMessage, message) -> combinedRaidLookup(chatMessage), this::publishToRelay);
		chatCommandManager.registerCommand(TOB_FALLBACK_COMMAND, (chatMessage, message) -> singleRaidLookup(chatMessage, RaidType.TOB), this::publishToRelay);

		panel = new RaidsLastPanel(raidLootTracker, itemManager, clientThread);
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navigationButton = NavigationButton.builder()
			.tooltip("Raids Last")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navigationButton);
	}

	@Override
	protected void shutDown()
	{
		chatCommandManager.unregisterCommand(COX_COMMAND);
		chatCommandManager.unregisterCommand(TOB_COMMAND);
		chatCommandManager.unregisterCommand(TOA_COMMAND);
		chatCommandManager.unregisterCommand(COMBINED_COMMAND);
		chatCommandManager.unregisterCommand(TOB_FALLBACK_COMMAND);

		clientToolbar.removeNavigation(navigationButton);
		panel = null;
		navigationButton = null;
	}

	@Subscribe
	public void onLootReceived(LootReceived lootReceived)
	{
		raidLootTracker.onLootReceived(lootReceived);
		panel.rebuild();
	}

	/**
	 * {@link #startUp()} builds (and renders empty) the panel before login, when there's no active
	 * RuneScape profile yet for its profile-scoped config to read from. Without a rebuild here, the
	 * panel stays stuck on that empty render until a drop or Collection Log widget happens to fire -
	 * even though the data was there the whole time, as the chat commands (which look it up fresh on
	 * demand) already showed.
	 */
	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		// Deferred a tick: this can fire before other game data (e.g. item caches the panel reads
		// while rendering) has finished loading for the new profile.
		clientThread.invokeLater(panel::rebuild);
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded widgetLoaded)
	{
		if (widgetLoaded.getGroupId() != RaidLootTracker.COLLECTION_OVERVIEW_GROUP_ID)
		{
			return;
		}

		clientThread.invokeLater(() ->
		{
			Widget latestItemsData = client.getWidget(InterfaceID.CollectionOverview.LATEST_ITEMS_DATA);
			if (latestItemsData == null)
			{
				return false;
			}

			raidLootTracker.seedFromCollectionLogOverview(latestItemsData);
			panel.rebuild();
			return true;
		});
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired scriptPostFired)
	{
		if (scriptPostFired.getScriptId() != ScriptID.COLLECTION_DRAW_LIST)
		{
			return;
		}

		clientThread.invokeLater(() ->
		{
			Widget pageHead = client.getWidget(InterfaceID.Collection.HEADER);
			Widget itemsContainer = client.getWidget(InterfaceID.Collection.ITEMS);
			if (pageHead == null || itemsContainer == null || pageHead.getDynamicChildren().length == 0)
			{
				return false;
			}

			String pageTitle = pageHead.getDynamicChildren()[0].getText();
			raidLootTracker.seedFromCollectionLogPage(pageTitle, itemsContainer);
			panel.rebuild();
			return true;
		});
	}

	/**
	 * This is a synchronous command, so it runs on the client thread - safe to touch
	 * {@link RaidLootTracker} directly for the default, local-only path. Only when
	 * {@link RaidsLastConfig#crossPlayerLookups()} is on does this need the network, and that work is
	 * explicitly handed off to {@link #executor} rather than blocking here, since a blocking HTTP call
	 * on the client thread would freeze the game.
	 */
	private void singleRaidLookup(ChatMessage chatMessage, RaidType raidType)
	{
		if (!config.crossPlayerLookups())
		{
			if (!isFromLocalPlayer(chatMessage))
			{
				return;
			}

			String response = new ChatMessageBuilder()
				.append(ChatColorType.NORMAL)
				.append(raidType.getLootEventName() + " last: ")
				.append(ChatColorType.HIGHLIGHT)
				.append(raidLootTracker.getLastItemName(raidType).orElse(NO_ITEM_YET))
				.build();

			setResponse(chatMessage, response);
			return;
		}

		String sender = resolveSenderName(chatMessage);
		executor.execute(() ->
		{
			Optional<String> itemName = raidsLastRelay.fetch(sender, raidType);
			if (!itemName.isPresent())
			{
				return;
			}

			String response = new ChatMessageBuilder()
				.append(ChatColorType.NORMAL)
				.append(raidType.getLootEventName() + " last: ")
				.append(ChatColorType.HIGHLIGHT)
				.append(itemName.get())
				.build();

			setResponse(chatMessage, response);
		});
	}

	private void combinedRaidLookup(ChatMessage chatMessage)
	{
		if (!config.crossPlayerLookups())
		{
			if (!isFromLocalPlayer(chatMessage))
			{
				return;
			}

			RaidType[] raidTypes = RaidType.values();
			ChatMessageBuilder builder = new ChatMessageBuilder();
			for (int i = 0; i < raidTypes.length; i++)
			{
				RaidType raidType = raidTypes[i];
				builder.append(ChatColorType.NORMAL)
					.append(raidType.getLootEventName() + " last: ")
					.append(ChatColorType.HIGHLIGHT)
					.append(raidLootTracker.getLastItemName(raidType).orElse(NO_ITEM_YET));

				if (i < raidTypes.length - 1)
				{
					builder.append(ChatColorType.NORMAL).append("\n");
				}
			}

			setResponse(chatMessage, builder.build());
			return;
		}

		String sender = resolveSenderName(chatMessage);
		executor.execute(() ->
		{
			RaidType[] raidTypes = RaidType.values();
			List<String> itemNames = new ArrayList<>(raidTypes.length);
			for (RaidType raidType : raidTypes)
			{
				Optional<String> itemName = raidsLastRelay.fetch(sender, raidType);
				if (!itemName.isPresent())
				{
					// Partial data would be more misleading than no answer at all.
					return;
				}
				itemNames.add(itemName.get());
			}

			ChatMessageBuilder builder = new ChatMessageBuilder();
			for (int i = 0; i < raidTypes.length; i++)
			{
				builder.append(ChatColorType.NORMAL)
					.append(raidTypes[i].getLootEventName() + " last: ")
					.append(ChatColorType.HIGHLIGHT)
					.append(itemNames.get(i));

				if (i < raidTypes.length - 1)
				{
					builder.append(ChatColorType.NORMAL).append("\n");
				}
			}

			setResponse(chatMessage, builder.build());
		});
	}

	private void setResponse(ChatMessage chatMessage, String response)
	{
		MessageNode messageNode = chatMessage.getMessageNode();
		messageNode.setRuneLiteFormatMessage(response);
		client.refreshChat();
	}

	/**
	 * Fires on the client thread, before this player's own command is actually sent. With
	 * {@link RaidsLastConfig#crossPlayerLookups()} off, this does nothing at all - not even a network
	 * request is made, since merely reaching the relay would expose this player's IP address to it.
	 * When on, it can safely read {@link RaidLootTracker} directly here (still the client thread) and
	 * only hands the actual HTTP work to {@link #executor}. The command's own send is held (returning
	 * {@code true} consumes it) until that publish completes, so anyone else's client can never
	 * receive this message before the data it needs exists.
	 */
	private boolean publishToRelay(ChatInput chatInput, String message)
	{
		if (!config.crossPlayerLookups())
		{
			return false;
		}

		String playerName = client.getLocalPlayer().getName();
		Map<RaidType, String> itemsByRaid = new EnumMap<>(RaidType.class);
		for (RaidType raidType : RaidType.values())
		{
			itemsByRaid.put(raidType, raidLootTracker.getLastItemName(raidType).orElse(NO_ITEM_YET));
		}

		executor.execute(() ->
		{
			try
			{
				for (Map.Entry<RaidType, String> entry : itemsByRaid.entrySet())
				{
					raidsLastRelay.publish(playerName, entry.getKey(), entry.getValue());
				}
			}
			finally
			{
				chatInput.resume();
			}
		});

		return true;
	}

	private String resolveSenderName(ChatMessage chatMessage)
	{
		return chatMessage.getType() == ChatMessageType.PRIVATECHATOUT
			? client.getLocalPlayer().getName()
			: Text.sanitize(chatMessage.getName());
	}

	/**
	 * Raid loot is only tracked for the local client, so with the relay off, the commands only have
	 * data to show off when the local player is the one who typed them.
	 */
	private boolean isFromLocalPlayer(ChatMessage chatMessage)
	{
		return resolveSenderName(chatMessage).equalsIgnoreCase(client.getLocalPlayer().getName());
	}
}

package com.raidslast;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.Locale;
import java.util.Optional;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Lets one player's own resolved answer reach another player's view of that same chat message.
 * RuneLite only ever renders a chat command's answer locally, for whichever client resolved it -
 * there's no channel from one player's client to another's except a server we stand up ourselves.
 * This is deliberately the smallest thing that works: a short-TTL Upstash Redis key per player per
 * raid, published right as a player's own command is about to send (so it's always there by the
 * time anyone else's client receives that same message, before any read of it is even attempted)
 * and read back by whoever is resolving somebody else's command. Nothing here persists past the
 * TTL - it's a relay, not a record of anyone's drops.
 *
 * The access token below is necessarily embedded in the distributed plugin jar, so it's effectively
 * public - anyone could write nonsense into this namespace. That's an accepted tradeoff: worst case
 * is bad/wrong answers, not exposure of anything sensitive, and it's what keeps this plugin free of
 * any server of its own to run and maintain.
 */
@Slf4j
class RaidsLastRelay
{
	private static final HttpUrl BASE_URL = HttpUrl.parse("https://accepted-lab-222105.upstash.io");
	private static final String TOKEN = "gQAAAAAAA2OZAAIgcDI2ZDRjNjdlODFlMTE0YzFmOGVmMjFjNWFkYmE3NjliMA";
	private static final int TTL_SECONDS = 20;

	private final OkHttpClient client;
	private final Gson gson;

	@Inject
	RaidsLastRelay(OkHttpClient client, Gson gson)
	{
		this.client = client;
		this.gson = gson;
	}

	/**
	 * Publishes this player's current last item for one raid. Best-effort: a failure here just means
	 * nobody else will be able to resolve this player's next command, so it's logged and swallowed
	 * rather than surfaced anywhere a player would see it.
	 */
	void publish(String playerName, RaidType raidType, String itemName)
	{
		HttpUrl url = BASE_URL.newBuilder()
			.addPathSegment("setex")
			.addPathSegment(key(playerName, raidType))
			.addPathSegment(String.valueOf(TTL_SECONDS))
			.addPathSegment(itemName)
			.build();

		Request request = new Request.Builder()
			.url(url)
			.header("Authorization", "Bearer " + TOKEN)
			.post(RequestBody.create(null, new byte[0]))
			.build();

		try (Response response = client.newCall(request).execute())
		{
			if (!response.isSuccessful())
			{
				log.debug("relay publish for {} {} failed: {}", playerName, raidType, response.code());
			}
		}
		catch (IOException e)
		{
			log.debug("relay publish for {} {} failed", playerName, raidType, e);
		}
	}

	/**
	 * Fetches another player's last item for one raid, as published by their own client. Empty means
	 * either that player's command never actually published this (older plugin version, or they've
	 * simply never run one), the key's already expired, or this one request failed - the
	 * publish-before-send guarantee on the write side means a retry here wouldn't be fixing a race,
	 * just masking a genuine request failure, so a single attempt is all this does.
	 */
	Optional<String> fetch(String playerName, RaidType raidType)
	{
		HttpUrl url = BASE_URL.newBuilder()
			.addPathSegment("get")
			.addPathSegment(key(playerName, raidType))
			.build();

		Request request = new Request.Builder()
			.url(url)
			.header("Authorization", "Bearer " + TOKEN)
			.build();

		try (Response response = client.newCall(request).execute())
		{
			if (!response.isSuccessful())
			{
				log.debug("relay fetch for {} {} failed: {}", playerName, raidType, response.code());
				return Optional.empty();
			}

			JsonObject body = gson.fromJson(response.body().charStream(), JsonObject.class);
			JsonElement result = body.get("result");
			if (result == null || result.isJsonNull())
			{
				return Optional.empty();
			}

			return Optional.of(result.getAsString());
		}
		catch (IOException e)
		{
			log.debug("relay fetch for {} {} failed", playerName, raidType, e);
			return Optional.empty();
		}
	}

	private static String key(String playerName, RaidType raidType)
	{
		return "raidslast:" + raidType.name() + ':' + playerName.toLowerCase(Locale.ROOT);
	}
}

